    checkHealth()
      .then(()=>setDbStatus("connected"))
      .catch(()=>setDbStatus("error"));
  }, []);

  return (
    <div style={{ minHeight: "100vh", position: "relative" }}>
      <StarField />

      {/* Nav */}
      <nav style={{ position: "sticky", top: 0, zIndex: 100, background: "rgba(2,4,8,0.85)", backdropFilter: "blur(16px)", borderBottom: "1px solid rgba(100,160,255,0.1)", padding: "12px 24px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <span style={{ fontSize: 20 }}>🚀</span>
          <span style={{ fontFamily: "'Orbitron',monospace", fontWeight: 700, fontSize: 14, color: "#a8ccff", letterSpacing: "0.08em" }}>ISRO PORTAL</span>
          <span style={{
            fontSize: 10,
            padding: "2px 8px",
            borderRadius: 6,
            border: "1px solid",
            ...(dbStatus === "connected"
              ? { background: "rgba(74,222,128,0.1)", borderColor: "rgba(74,222,128,0.3)", color: "#4ade80" }
              : dbStatus === "error"
                ? { background: "rgba(248,113,113,0.1)", borderColor: "rgba(248,113,113,0.3)", color: "#f87171" }
                : { background: "rgba(250,204,21,0.1)", borderColor: "rgba(250,204,21,0.3)", color: "#facc15", animation: "pulse 1.5s infinite" })
          }}>
            {dbStatus === "connected" ? "● DB LIVE" : dbStatus === "error" ? "● DB ERROR" : "● CONNECTING"}
          </span>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
        {[["user", "🌍 Explorer"], ["admin", "⚙️ Admin"]].map(([v, l]) => (
          <button key={v} onClick={() => setView(v)}
            style={{ background: view === v ? (v === "admin" ? "rgba(250,204,21,0.15)" : "rgba(100,160,255,0.15)") : "transparent", border: `1px solid ${view === v ? (v === "admin" ? "rgba(250,204,21,0.4)" : "rgba(100,160,255,0.4)") : "rgba(255,255,255,0.1)"}`, color: view === v ? (v === "admin" ? "#facc15" : "#7eb8ff") : "rgba(180,200,255,0.5)", borderRadius: 8, padding: "7px 16px", fontSize: 13, cursor: "pointer", transition: "all 0.2s" }}>
            {l}
          </button>
        ))}
      </div>
      </nav>

      {/* Content */}
      <div style={{ position:"relative", zIndex:1 }}>
